import json,re
from pathlib import Path

data=json.loads(Path('benchmark/source_data.json').read_text())

# Build quarter -> events list (downgrade/default) mapping
# map YYYY-MM to quarter

def month_to_quarter(ym):
    y,m=ym.split('-');y=int(y);m=int(m)
    q=(m-1)//3+1
    return f"{y}-Q{q}" 

q_events={}
for r in data['sovereign_rating_changes']['data']:
    if r['action'] in ('downgrade','default'):
        q=month_to_quarter(r['date'])
        q_events.setdefault(q,[]).append((r['country'],r['action'],r['rating_level'],r['date']))

for q in sorted(q_events.keys(), key=lambda s:(int(s[:4]), int(s[-1]))):
    ev=q_events[q]
    print(q, len(ev), ev)
